package org.apache.commons.lang3;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.Locale;
import org.apache.commons.lang3.text.WordUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for StringUtils.containsNone(CharSequence, char[])
 */
public class StringUtils_containsNone_TriageGen1Test {

    @Test
    public void testContainsNone_NullInputs() {
        // If cs is null, returns true
        assertTrue(StringUtils.containsNone(null, new char[]{'a'}));
        // If searchChars is null, returns true
        assertTrue(StringUtils.containsNone("abc", null));
        // If both are null, returns true
        assertTrue(StringUtils.containsNone(null, null));
    }

    @Test
    public void testContainsNone_EmptyInputs() {
        // Empty cs, returns true (contains none of the chars because there are no chars)
        assertTrue(StringUtils.containsNone("", new char[]{'a', 'b'}));
        // Empty searchChars, returns true
        assertTrue(StringUtils.containsNone("abc", new char[]{}));
    }

    @Test
    public void testContainsNone_NoMatch() {
        // None of the characters in cs are in searchChars
        assertTrue(StringUtils.containsNone("abc", new char[]{'d', 'e', 'f'}));
        // Test with different order and values
        assertTrue(StringUtils.containsNone("123", new char[]{'4', '5'}));
    }

    @Test
    public void testContainsNone_WithMatch() {
        // 'a' is in searchChars
        assertFalse(StringUtils.containsNone("abc", new char[]{'a', 'b'}));
        // 'c' is in searchChars
        assertFalse(StringUtils.containsNone("abc", new char[]{'c'}));
        // Single char match
        assertFalse(StringUtils.containsNone("a", new char[]{'a'}));
    }

    @Test
    public void testContainsNone_BMP_Match() {
        // Test Basic Multilingual Plane (BMP) match logic
        // The code uses (searchChars[j] >= ch) logic which is slightly unusual for a "contains" check,
        // but we must test the branches provided in the snippet.
        // In the provided code: if (searchChars[j] >= ch) -> return false

        // Case: searchChars[j] == ch (matches)
        assertFalse(StringUtils.containsNone("a", new char[]{'a'}));

        // Case: searchChars[j] > ch (triggers the branch in the provided snippet)
        assertFalse(StringUtils.containsNone("a", new char[]{'b'}));
    }

    @Test
    public void testContainsNone_HighSurrogate_Match() {
        // Testing the high surrogate branches
        // Emoji: 𝄞 (U+1D11E) -> High Surrogate: \uD834, Low Surrogate: \uDD1E
        char high = '\uD834';
        char low = '\uDD1E';
        String surrogateStr = "" + high + low;

        // Branch: Character.isHighSurrogate(ch) is true AND j == searchLast (missing low surrogate case)
        // If searchChars only contains the high surrogate, it returns false (meaning it "contains" it)
        // Wait, logic check: if (j == searchLast) return false; 
        // In the context of this specific implementation, returning false means "found the forbidden char"
        // But the code says: if (j == searchLast) return false; -> This effectively means it found a match.

        char[] searchHighOnly = new char[]{high};
        assertFalse(StringUtils.containsNone(surrogateStr, searchHighOnly));

        // Branch: i < csLast && searchChars[j + 1] == cs.charAt(i + 1)
        // Full surrogate match
        char[] searchFullSurrogate = new char[]{high, low};
        assertFalse(StringUtils.containsNone(surrogateStr, searchFullSurrogate));

        // Branch: High surrogate but no match on next char
        char[] searchWrongLow = new char[]{high, '\uDD1F'};
        // If it's high surrogate and j+1 doesn't match, it falls through the inner loop
        // If the loop finishes without returning false, it returns true.
        // However, the code logic is: if (searchChars[j] >= ch)
        // Let's test a char that doesn't trigger the 'if'
        assertTrue(StringUtils.containsNone("abc", new char[]{'!'})); 
    }

    @Test
    public void testContainsNone_ComplexBranching() {
        // Testing the 'searchChars[j] >= ch' logic specifically
        // If ch = 'b' and searchChars[j] = 'c', 'c' >= 'b' is true.
        // The method returns false (meaning it found a char it shouldn't have).
        assertFalse(StringUtils.containsNone("b", new char[]{'c'}));

        // If ch = 'b' and searchChars[j] = 'a', 'a' >= 'b' is false.
        // It continues.
        assertTrue(StringUtils.containsNone("b", new char[]{'a'}));
    }
}
